 doublewashed:pr({name:'Double washed (Kenyan style)',cat:'classic',t:0.2,acid:1.3,body:-0.2,sweet:0.1,notes:['juicy','bright','very clean'],dir:'baseline',char:'Fermented, washed, then fermented or soaked again in clean water. Common in Kenya. Extra clarity and juicy acidity.',brew:'Baseline grind, 92 to 94°C. Coarsen if the acidity turns sharp.'}),
 ecopulped:pr({name:'Eco-pulped (mechanically demucilaged)',cat:'classic',t:0.15,acid:0.6,body:0,notes:['clean','balanced'],dir:'baseline',char:'The mucilage is scrubbed off by machine instead of fermented away, saving water. Tastes like a slightly softer washed coffee.',brew:'Treat like washed, a touch coarser.'}),
 natural:pr({name:'Natural (dry)',cat:'classic',t:-0.35,acid:-0.4,body:1,sweet:0.6,funk:0.6,notes:['jammy','ripe fruit'],dir:'coarser',char:'The whole cherry is dried with the bean inside, on patios or raised beds. Jammy, sweet, sometimes boozy, lower acidity.',brew:'Coarser, 90 to 92°C, gentler pours. You are chasing definition.'}),
 pulpednatural:pr({name:'Pulped natural',cat:'classic',t:-0.1,acid:0,body:0.6,sweet:0.5,funk:0.2,notes:['nutty','caramel','round'],dir:'baseline',char:'Brazil\u2019s version of honey: the skin is removed and the bean dried with its mucilage. Sweet, round, low acidity.',brew:'Baseline grind, 92 to 93°C.'}),
 wethulled:pr({name:'Wet-hulled (giling basah)',cat:'regional',t:-0.3,acid:-1.2,body:1.3,sweet:0.2,funk:0.8,notes:['earthy','herbal'],dir:'coarser',char:'Indonesian: the parchment is removed while the bean is still wet, then dried. Earthy, herbal, cedar, heavy body, very low acidity.',brew:'Coarser and cooler, 90 to 92°C.'}),
 honey:pr({name:'Honey (general)',cat:'honey',t:0,acid:0.3,body:0.3,sweet:0.3,funk:0.2,notes:['honeyed','rounded'],dir:'baseline',char:'Skin removed, some or all of the sticky mucilage left on while drying. Sweeter than washed, cleaner than natural.',brew:'Just coarse of your washed setting, 92 to 93°C.'}),
 whitehoney:pr({name:'White and yellow honey',cat:'honey',t:0.1,acid:0.6,body:0.1,sweet:0.2,funk:0.1,notes:['clean','honeyed'],dir:'baseline',char:'Little mucilage left and quick drying. Very close to washed, with a touch more sweetness.',brew:'Treat almost like washed.'}),
 redhoney:pr({name:'Red honey',cat:'honey',t:-0.05,acid:0.3,body:0.4,sweet:0.4,funk:0.3,notes:['red fruit','honey'],dir:'baseline',char:'More mucilage and slower, shaded drying. Fruitier and heavier.',brew:'Baseline, 92°C.'}),
 blackhoney:pr({name:'Black honey',cat:'honey',t:-0.25,acid:0,body:0.8,sweet:0.6,funk:0.5,notes:['dark fruit','molasses'],dir:'coarser',char:'Maximum mucilage, slow drying, often covered. Closest to a natural: dark fruit, syrupy.',brew:'Treat almost like a natural: coarser, 91 to 92°C.'}),
 anaerobic:pr({name:'Anaerobic',cat:'ferment',t:-0.6,acid:-0.2,body:1.2,sweet:0.5,funk:1.2,notes:['tropical','boozy','spice'],dir:'coarser',char:'Fermented in sealed, oxygen-free tanks. Intense ferment, tropical fruit, cinnamon and spice.',brew:'Coarsest and coolest, 88 to 91°C, a 30 to 35s bloom, minimal agitation.'}),
 anaerobicnatural:pr({name:'Anaerobic natural',cat:'ferment',t:-0.7,acid:-0.3,body:1.3,sweet:0.7,funk:1.4,notes:['candied fruit','boozy','winey'],dir:'coarser',char:'Whole cherries sealed and fermented, then dried as a natural. The loudest of the classic anaerobics.',brew:'Coarse and cool, 88 to 90°C, very gentle.'}),
 anaerobicwashed:pr({name:'Anaerobic washed',cat:'ferment',t:-0.35,acid:0.4,body:0.6,sweet:0.4,funk:0.8,notes:['tropical','clean ferment'],dir:'coarser',char:'Pulped beans fermented sealed, then washed. Ferment character with a cleaner finish.',brew:'Slightly coarse, 90 to 92°C.'}),
 carbonic:pr({name:'Carbonic maceration',cat:'ferment',t:-0.5,acid:0.2,body:0.8,sweet:0.6,funk:1,notes:['red wine','cinnamon','grape'],dir:'coarser',char:'Borrowed from winemaking: whole cherries fermented in tanks flushed with carbon dioxide. Brought to fame when Sasa Sestic won the 2015 World Barista Championship with it.',brew:'Coarse, 90 to 91°C, gentle.'}),
 lactic:pr({name:'Lactic',cat:'ferment',t:-0.3,acid:-0.2,body:0.8,sweet:0.5,funk:0.7,notes:['creamy','yoghurt','soft acidity'],dir:'coarser',char:'Anaerobic conditions that favour lactic acid bacteria. Creamy, round, soft yoghurt-like acidity.',brew:'Slightly coarse, 91 to 92°C.'}),
 yeast:pr({name:'Yeast inoculated',cat:'ferment',t:-0.2,acid:0.3,body:0.5,sweet:0.5,funk:0.5,notes:['clean fruit','floral'],dir:'baseline',char:'Selected wine or beer yeasts are added to steer the fermentation. Cleaner, more controlled fruit.',brew:'Baseline to slightly coarse, 92°C.'}),
 koji:pr({name:'Koji fermentation',cat:'ferment',t:-0.3,acid:-0.2,body:0.8,sweet:0.6,funk:0.8,notes:['sake','umami','sweet'],dir:'coarser',char:'Inoculated with koji (Aspergillus oryzae), the mould used for sake and miso. Savoury-sweet, rice-wine notes.',brew:'Slightly coarse, 91 to 92°C.'}),
 extended:pr({name:'Extended fermentation',cat:'ferment',t:-0.45,acid:0,body:0.9,sweet:0.5,funk:1,notes:['winey','ripe fruit'],dir:'coarser',char:'Fermentations stretched to days rather than hours, in cherry or in tanks. Deep, winey fruit.',brew:'Coarse, 90 to 91°C.'}),
