 mossto:pr({name:'Mossto',cat:'ferment',t:-0.55,acid:0,body:1,sweet:0.7,funk:1.2,notes:['concentrated fruit','boozy'],dir:'coarser',char:'A Colombian technique: juice (must) from an earlier fermentation is added to start a new one, amplifying fruit.',brew:'Coarse and cool, 88 to 91°C.'}),
 coferment:pr({name:'Co-ferment',cat:'ferment',t:-0.75,acid:0,body:1,sweet:0.6,funk:1.6,notes:['added fruit','candy-like'],dir:'coarser',char:'Fermented with added fruit, spices or cultures. Extremely loud, often divisive.',brew:'Coarse, cool, gentle. A longer ratio softens the intensity.'}),
 infused:pr({name:'Infused',cat:'ferment',t:-0.6,acid:-0.2,body:0.6,sweet:0.8,funk:1.3,notes:['flavoured','very sweet'],dir:'coarser',char:'Flavourings such as fruit concentrates or spices are added to the beans. Controversial, and not allowed in some competitions; ask the roaster.',brew:'Coarse and cool so the added flavour does not turn harsh.'}),
 barrelaged:pr({name:'Barrel-aged',cat:'regional',t:-0.3,acid:-0.4,body:1,sweet:0.6,funk:0.8,notes:['whisky','oak','vanilla'],dir:'coarser',char:'Green beans rested in used spirit barrels (whisky, rum, wine) before roasting.',brew:'Slightly coarse, 91 to 92°C.'}),
 monsooned:pr({name:'Monsooned',cat:'regional',t:-0.2,acid:-1.5,body:1.2,funk:0.8,notes:['musty','spice','woody'],dir:'coarser',char:'Indian (Malabar): beans exposed to humid monsoon winds for months, swelling and turning pale. Very low acidity.',brew:'Coarser, 90°C.'}),
 aged:pr({name:'Aged green coffee',cat:'regional',t:-0.2,acid:-1,body:0.8,funk:0.6,notes:['woody','spice','cedar'],dir:'coarser',char:'Green coffee deliberately stored for years, traditionally Indonesian. Woody, spicy, low acidity.',brew:'Coarser, 90 to 92°C.'}),
 swisswater:pr({name:'Swiss Water decaf',cat:'decaf',t:-0.2,acid:-0.2,body:-0.2,notes:['soft','sweet'],dir:'coarser',char:'Caffeine removed with water and carbon filters, no added chemicals.',brew:'Decaf beans are more porous and extract fast: coarser and a bit cooler.'}),
 sugarcane:pr({name:'Sugarcane (EA) decaf',cat:'decaf',t:-0.2,acid:0,body:-0.1,sweet:0.2,notes:['sweet','fruity'],dir:'coarser',char:'Caffeine removed with ethyl acetate made from fermented sugarcane. Often keeps sweetness well.',brew:'Coarser and a bit cooler than the same coffee undecaffeinated.'}),
