 mcdecaf:pr({name:'Solvent decaf (methylene chloride)',cat:'decaf',t:-0.2,acid:-0.1,body:-0.1,notes:['mild'],dir:'coarser',char:'The traditional "European process". Solvent residues are removed by roasting; regulated limits apply.',brew:'Coarser and a bit cooler.'})
